--- 在战中检测 低端阴影 的工具, 可接入 BattleViewMgr



---@class LowShadowCheckToolInBattle
local LowShadowCheckToolInBattle = Class('LowShadowCheckToolInBattle')
-- 外部访问时使用:
-- local LowShadowCheckToolInBattle = import("Game.CheckTools.LowShadowCheckToolInBattle")


-- ========================================================



local ResourceModule = CS.Engine.Modules.ResourceModule -- 资源加载
local Application = CS.UnityEngine.Application
local GameObject = CS.UnityEngine.GameObject
local Vector3 = CS.UnityEngine.Vector3
local Transform = CS.UnityEngine.Transform
local MeshRenderer = CS.UnityEngine.MeshRenderer

local FuntoyRenderFeature = CS.FuntoyRenderFeature
local PlaneShadowQuality = CS.FuntoyRenderFeature.PlaneShadowQuality


local URPCameraController = CS.Game.Native.URP.URPCameraController


-- ========================================================


local TotalActive = false -- 总开关


-- ========================================================


function LowShadowCheckToolInBattle:__init()
    self.tgtGOS = {}
    self.frameIdx = 0
    ---
    self.isInit = true
end




function LowShadowCheckToolInBattle:__delete()
    self.tgtGOS = nil
    self.frameIdx = 0
end



function LowShadowCheckToolInBattle:AddRoleGameObj( go_ )
    if TotalActive ~= true then 
        return
    end 
    if self.isInit ~= true then 
        return
    end 

    printError("koko 战斗场景新增: " .. tostring(go_.name) )
    table.insert( self.tgtGOS, go_ )
end


function LowShadowCheckToolInBattle:SelfUpdate()
    if TotalActive ~= true then 
        return
    end 
    if self.isInit ~= true then 
        return
    end 
    -- N帧一次:
    self.frameIdx = self.frameIdx + 1
    if self.frameIdx % 90 ~= 1 then 
        return
    end 
    ---
    local activGos = {}
    for k,go_ in pairs(self.tgtGOS) do 
        if isNotNull(go_) then 
            table.insert( activGos, go_ )
        end
    end
    --printError("koko gos num = " .. tostring( table.count(activGos) ))
    for k,go_ in pairs(activGos) do 
        self:_CheckTprGo(go_)
    end
end



function LowShadowCheckToolInBattle:_CheckTprGo( go_ )

    local LowDiscShadowMR = self:_FindTprGoShadow(go_)

    if LowDiscShadowMR ~= nil then 
        if FuntoyRenderFeature.planeShadowQuality == PlaneShadowQuality.Low then

            if  LowDiscShadowMR.enable == false then 

                local log = "koko 阴影: " .. tostring(go_.name) .. " 的 MeshRenderer 组件没开"
                printError( log )
                GameUtils.Toast( log )

            end 

        end
    end

end



function LowShadowCheckToolInBattle:_FindTprGoShadow( go_ )
    local mrs = go_.transform:GetComponentsInChildren(typeof(MeshRenderer),true)
    for i=0, mrs.Length-1 do 
        local mr = mrs[i]
        if mr.name == "LowDiscShadow" then 
            return mr
        end
    end
    local log = "koko 在 " .. tostring(go_.name) .. " 中没找到 LowDiscShadow 的 MeshRenderer 组件"
    printError( log )
    GameUtils.Toast( log )
    return nil
end




return LowShadowCheckToolInBattle
